function extractStation(text, buttonValue) {
  const candidates = [
    toStr(buttonValue)?.toLowerCase(),
    toStr(text)?.toLowerCase(),
  ].filter(Boolean);

  for (const candidate of candidates) {
    if (stationMap.has(candidate)) {
      return stationMap.get(candidate);
    }
  }
  return null;
}

