function resolveEventType(update) {
  if (update.command === "/start") {
    return "START";
  }
  if (update.messageKind === "contact" && update.contact?.phone) {
    return "CONTACT_SHARED";
  }
  if (update.messageKind === "station" && update.station) {
    return "STATION_SELECTED";
  }
  return "MESSAGE";
}

